int adim = 0; // Form seviyesinde durum sayacı

private void btnBaslat_Click(object sender, EventArgs e)
{
    timer1.Start(); // veya timer1.Enabled = true;
    lblDurum.Text = "Trafik Işığı Devrede...";
}

private void btnDurdur_Click(object sender, EventArgs e)
{
    timer1.Stop(); // veya timer1.Enabled = false;
    lblDurum.Text = "Sistem Durduruldu!";
}

private void timer1_Tick(object sender, EventArgs e)
{
    adim++;
    switch (adim)
    {
        case 1: // KIRMIZI
            pnlKirmizi.BackColor = Color.Red;
            pnlSari.BackColor = Color.Gray;
            pnlYesil.BackColor = Color.Gray;
            lblDurum.Text = "🛑 DUR!";
            break;
        case 2: // SARI
            pnlKirmizi.BackColor = Color.Red;
            pnlSari.BackColor = Color.Yellow;
            pnlYesil.BackColor = Color.Gray;
            lblDurum.Text = "⚠️ HAZIRLAN!";
            break;
        case 3: // YEŞİL
            pnlKirmizi.BackColor = Color.Gray;
            pnlSari.BackColor = Color.Gray;
            pnlYesil.BackColor = Color.LimeGreen;
            lblDurum.Text = "🟢 GEÇ!";
            break;
        default:
            adim = 0; // Başa dön
            break;
    }
}

10 katlı bir binanın asansör motoru:
switch (hedefKat)
{
    case 0: ZeminKattaDur(); break;
    case 1: BirinciKattaDur(); break;
    case 5: BesinciKattaDur(); break;
}
Asansör sistemleri klasik durum makinesi mantığıyla switch-case üzerinden yönetilir.

Yeni nesil C# sürümlerinde switch ifadesi lambda (=>) ile çok daha kısa yazılabilir:

string mevsim = ay switch
{
    12 or 1 or 2 => "Kış",
    3 or 4 or 5  => "İlkbahar",
    6 or 7 or 8  => "Yaz",
    _            => "Geçersiz Ay"
};
Bu sentaks kod satır sayısını yarı yarıya azaltır.

C# 7.0 ile birlikte switch içine tip kontrolleri ve 'when' şartları eklenebilmiştir:

switch (nesne)
{
    case int i when i > 100: lblSonuc.Text = "Büyük Sayı"; break;
    case string s: lblSonuc.Text = "Metin: " + s; break;
}

int saniye = 0;
int dakika = 0;

private void timer1_Tick(object sender, EventArgs e)
{
    saniye++;
    if (saniye == 60) { dakika++; saniye = 0; }
    lblKronometre.Text = dakika.ToString("00") + ":" + saniye.ToString("00");
}

Bir butonu veya paneli sağa doğru kaydırmak için:

private void timer1_Tick(object sender, EventArgs e)
{
    btnAraba.Left += 5; // Her saniye 5 piksel sağa kaydır
    if (btnAraba.Left > this.Width) btnAraba.Left = 0; // Başa dön
}

Çamaşır makinesinin yuvarlak ayar düğmesi:
switch (secilenProgram)
{
    case "Pamuklu": Sure = 120; Sicaklik = 60; break;
    case "Hızlı 15'": Sure = 15; Sicaklik = 30; break;
    case "Sıkma": Sure = 10; SıkmaDevri = 1000; break;
}
Gömülü sistemlerin program seçim mekanizması switch-case ile kurulur.

